B.bbK=new A.Y("O M\xe3o na Roda, operado pela Impetus Tecnologia, \xe9 uma plataforma de intermedia\xe7\xe3o e conveni\xeancia que conecta clientes tomadores de servi\xe7os a profissionais prestadores parceiros aut\xf4nomos.",null,B.ev,null,null,null,null,null,null,null,null,null,null)
B.b8W=new A.Y("2. CUST\xd3DIA FINANCEIRA SEGURA (ESCROW)",null,B.e2,null,null,null,null,null,null,null,null,null,null)
B.bbW=new A.Y("Todo valor pago (via PIX ou Cart\xe3o de Cr\xe9dito) \xe9 mantido em cust\xf3dia protegida pela plataforma. O valor s\xf3 \xe9 transferido para a carteira do prestador ap\xf3s a confirma\xe7\xe3o e aprova\xe7\xe3o expressa do servi\xe7o pelo cliente.",null,B.ev,null,null,null,null,null,null,null,null,null,null)
