B.bbc=new A.Y("A plataforma ret\xe9m uma taxa de intermedia\xe7\xe3o e seguran\xe7a de 10% sobre o valor total do chamado, repassando 90% l\xedquido ao prestador do atendimento.",null,B.ev,null,null,null,null,null,null,null,null,null,null)
B.b9M=new A.Y("4. PRAZOS E PONTUALIDADE",null,B.e2,null,null,null,null,null,null,null,null,null,null)
B.baO=new A.Y("O prestador deve cumprir os prazos de deslocamento:\n\u2022 At\xe9 1 km de dist\xe2ncia: chegada em at\xe9 30 minutos.\n\u2022 Acima de 1 km: chegada em at\xe9 1 hora.\nO n\xe3o comparecimento sem justificativa enseja penalidades e cancelamento do chamado.",null,B.ev,null,null,null,null,null,null,null,null,null,null)
